              function sanitizeUrlProtocols(s) {
                return s.replace(/(?<![-\/\w])([A-Za-z][A-Za-z0-9+.-]*):(?:\/\/|(?=[^\s:]))[^\s\])}'"<>&\x00-\x1f]+/g, (match, protocol) => {
                  if (protocol.toLowerCase() === "https") {
