                  }
                  if (match.includes("::")) {
                    return match;
                  }
                  if (match.includes("://")) {
                    const domainMatch = match.match(/^[^:]+:\/\/([^\/\s?#]+)/);
                    const domain = domainMatch ? domainMatch[1] : match;
                    const truncated = domain.length > 12 ? domain.substring(0, 12) + "..." : domain;
                    core.info(`Redacted URL: ${truncated}`);
