              sanitized = sanitizeUrlProtocols(sanitized);
              sanitized = sanitizeUrlDomains(sanitized);
              const lines = sanitized.split("\n");
              const maxLines = 65000;
              maxLength = maxLength || 524288;
              if (lines.length > maxLines) {
