                  }
                  core.info(`   Reported at: ${tool.timestamp}`);
                  core.info("");
                  core.summary.addRaw(`### ${index + 1}. \`${tool.tool}\`\n\n`).addRaw(`**Reason:** ${tool.reason}\n\n`);
                  if (tool.alternatives) {
