                      id
                      discussionCategories(first: 20) {
                        nodes {
                          id
                          name
                          slug
                          description
                        }
                      }
                    }
                  }
                `;
                const queryResult = await github.graphql(repositoryQuery, {
                  owner: context.repo.owner,
