              const v = expr.trim().toLowerCase();
              return !(v === "" || v === "false" || v === "0" || v === "null" || v === "undefined");
            }
            function interpolateVariables(content, variables) {
              let result = content;
              for (const [varName, value] of Object.entries(variables)) {
